import React from 'react';

import { TextEllipsis } from '../../../../../../typography/TextEllipsis.js';
import { DEFAULT_TRUNCATION_MODE } from '../../../../constants.js';
import { PrimaryAtom } from '../../../tooltip-atoms/components/PrimaryAtom.js';
import { SecondaryAtom } from '../../../tooltip-atoms/components/SecondaryAtom.js';
import { TooltipTextProps } from '../../types/ChartTooltip.config.js';

export const TooltipText = (props: TooltipTextProps) => {
  const { children, variant = 'primary', truncationMode, ...rest } = props;

  return variant === 'primary' ? (
    <PrimaryAtom {...rest}>
      {
        <TextEllipsis
          truncationMode={truncationMode ?? DEFAULT_TRUNCATION_MODE}
          aria-label="Primary serie name"
        >
          {children as string}
        </TextEllipsis>
      }
    </PrimaryAtom>
  ) : (
    <SecondaryAtom {...rest}>
      <TextEllipsis
        truncationMode={truncationMode ?? DEFAULT_TRUNCATION_MODE}
        aria-label="Secondary serie name"
      >
        {children as string}
      </TextEllipsis>
    </SecondaryAtom>
  );
};

TooltipText['displayName'] = 'TooltipText';
